import React from 'react';
import { Meta, Story } from '@storybook/react';
import { ToastTypes, Button, Toast } from '../..';

export default {
  title: 'Feedback/Toast',
  component: Toast.Root,
  parameters: {
    docs: {
      description: {
        component:
          'The Toast component is rendered using the container available. For that reason the examples can appear considering the storybook canvas or the screen. The duration and the swipeDirection props need to be passed to the `Toast.Provider` component. To have toast in different positions you need to have different `Toast.Providers`.<br><br>How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Toast } from "@hexa-ui/components"`<br><br>How to use: `Toast.Provider` and `Toast.Root` or destructure it `{ Provider, Root } = Toast`',
      },
    },
  },
} as Meta;

export const ToastExample: Story<ToastTypes> = (args) => {
  const [open, setOpen] = React.useState(false);
  const handleOpen = () => {
    setOpen(true);
  };
  return (
    <Toast.Provider swipeDirection="right" duration={3000}>
      <Button size="medium" onClick={() => handleOpen()}>
        Open
      </Button>
      <Toast.Root
        type="info"
        open={open}
        onOpenChange={setOpen}
        position="top-right"
        message="Lorem ipsum dolor sit amet, consectetur adipiscing elit"
        {...args}
      />
    </Toast.Provider>
  );
};

export const ToastError: Story<ToastTypes> = (args) => {
  const [open, setOpen] = React.useState(false);
  const handleOpen = () => {
    setOpen(true);
  };
  return (
    <Toast.Provider swipeDirection="right" duration={3000}>
      <Button size="medium" onClick={() => handleOpen()}>
        Open
      </Button>
      <Toast.Root
        type="error"
        open={open}
        onOpenChange={setOpen}
        position="top-right"
        message="Lorem ipsum dolor sit amet, consectetur adipiscing elit"
        actions={[{ name: 'Action One', action: () => console.log('working') }]}
        showCloseButton
        onClose={() => setOpen(false)}
        {...args}
      />
    </Toast.Provider>
  );
};

