export const ToastWithActions: Story<ToastTypes> = (args) => {
  const [open, setOpen] = React.useState(false);
  const handleOpen = () => {
    setOpen(true);
  };
  return (
    <Toast.Provider swipeDirection="right" duration={8000}>
      <Button
        size="medium"
        onClick={() => {
          handleOpen();
        }}
      >
        Open
      </Button>
      <Toast.Root
        type="warning"
        open={open}
        onOpenChange={setOpen}
        position="bottom-left"
        message="Warning"
        actions={[
          { name: 'Action One', action: () => console.log('working') },
          { name: 'Action Two', action: () => console.log('working') },
        ]}
        showCloseButton
        onClose={() => setOpen(false)}
        {...args}
      />
    </Toast.Provider>
  );
};
